import { usePasswordVisibility } from './usePasswordVisibility';
import './styles.css';

export type Props = { initialValue: string; onChange: (value: string) => void };

export function Component(props: Props) {
  const { value, visible, updateValue, toggle } = usePasswordVisibility(props);

  return (
    <section data-testid="panel" className="password-panel">
      <label>
        Password
        <input
          type={visible ? 'text' : 'password'}
          value={value}
          onChange={event => updateValue(event.currentTarget.value)}
        />
      </label>
      <button type="button" aria-pressed={visible} onClick={toggle}>Toggle visibility</button>
    </section>
  );
}

